<button type="button" data-theme-toggle aria-label="Switch colour theme" title="Switch between light and dark"
        class="group relative inline-flex h-9 w-9 items-center justify-center rounded-full border border-line-strong bg-surface text-muted transition hover:border-accent hover:text-accent-ink">
    {{-- sun (shown in dark mode: click for light) --}}
    <svg class="hidden h-[18px] w-[18px] dark:block" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>
    {{-- moon (shown in light mode: click for dark) --}}
    <svg class="block h-[18px] w-[18px] dark:hidden" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg>
</button>
